const NOTICE_TEXT = "New message from the website contact form.\n\nTopic: {{topic}}\nName:  {{name}}\nEmail: {{email}}\nIP:    {{ip}}\n\n{{message}}\n";

// Equivalent to Python's html.escape(quote=True), including &#x27; for the
// apostrophe. The equivalence is asserted at generation time against a corpus of
// hostile inputs; see NASTY in src/letterhead/snippet.py.
export function houseEscape(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

function fillHtml(template, fields) {
  return template.replace(/\{\{(\w+)\}\}/g, function (_match, name) {
    return houseEscape(fields[name]);
  });
}

// The plain-text half is NOT markup, so it must NOT be escaped. One fill()
// did both halves, which meant an officer opening the notification read
// "AT&amp;T" and "&lt;no subject&gt;" in the plain-text body, and a message
// quoting anything came through mangled. Escaping is a property of the
// destination, not of the value. Audit 2026-08-10, ASTRO-01.
//
// Nothing is lost by not escaping here: this string is a text/plain email
// body. It is never parsed as markup, so there is no injection to prevent,
// only characters to preserve.
function fillText(template, fields) {
  return template.replace(/\{\{(\w+)\}\}/g, function (_match, name) {
    var value = fields[name];
    return String(value == null ? "" : value);
  });
}

// Takes the contact-form fields topic, name, email, ip and message.
// Returns an object with an html property and a text property.
export function renderNotice(fields) {
  return {
    html: fillHtml(NOTICE_HTML, fields),
    text: fillText(NOTICE_TEXT, fields),
  };
}

